import type { PlanDay, PlanRequest, PlanResponse } from "@/types/plan";

const DISCLAIMER =
  "DEMO CONTENT: this itinerary, packing list, and budget are sample data " +
  "for UI development. They are not generated by the real fine-tuned model.";

function countDays(startDate: string, endDate: string): number {
  const start = new Date(startDate);
  const end = new Date(endDate);
  const diff = Math.round((end.getTime() - start.getTime()) / (1000 * 60 * 60 * 24));
  return Math.max(diff + 1, 1);
}

function addIsoDays(isoDate: string, offsetDays: number): string {
  const date = new Date(`${isoDate}T00:00:00Z`);
  date.setUTCDate(date.getUTCDate() + offsetDays);
  return date.toISOString().slice(0, 10);
}

function inferMaxDistanceKm(constraints: string | undefined): number {
  const text = (constraints ?? "").toLowerCase();
  if (/beginner|knee|elderly|kid|child|toddler|asthma|pregnan/.test(text)) {
    return 6;
  }
  if (/advanced|experienced|expert/.test(text)) {
    return 20;
  }
  return 12;
}

function inferBudgetTotal(constraints: string | undefined): number {
  const match = (constraints ?? "").match(/(\d{3,6})/);
  return match ? Number(match[1]) : 5000;
}

export function generateMockPlanResponse(request: PlanRequest): PlanResponse {
  const maxDistanceKm = inferMaxDistanceKm(request.constraints);
  const budgetTotal = inferBudgetTotal(request.constraints);
  const dayCount = countDays(request.startDate, request.endDate);

  const days: PlanDay[] = Array.from({ length: dayCount }, (_, index) => ({
    day: index + 1,
    date: addIsoDays(request.startDate, index),
    activity:
      index === 0
        ? `Arrival and gentle acclimatization walk around ${request.place}.`
        : `Outdoor trail near ${request.place}, paced for the stated constraints.`,
    distanceKm: index === 0 ? Math.min(3, maxDistanceKm) : Math.min(maxDistanceKm, 5 + index),
  }));

  const packing = [
    "Weatherproof jacket",
    "Sturdy walking shoes with ankle support",
    maxDistanceKm <= 6 ? "Knee support brace" : "Trekking poles",
    "Reusable water bottle",
    "First-aid kit",
    "Power bank",
    "Offline maps downloaded in advance",
  ];

  const warnings = [
    "Check local landslide and weather advisories before departure (see risk assessment).",
    "Avoid trails during or immediately after heavy rainfall.",
    request.riskVerdict === "WAIT"
      ? "Risk verdict was WAIT for these dates, consider rescheduling outdoor activities."
      : "Carry a basic first-aid kit and know the nearest medical facility location.",
  ];

  const overDistance = days.some((d) => d.distanceKm > maxDistanceKm);

  return {
    destination: request.place,
    startDate: request.startDate,
    endDate: request.endDate,
    days,
    packing,
    warnings,
    budgetEstimate: { currency: "INR", total: budgetTotal },
    checksPassed: !overDistance && packing.length > 0 && days.length > 0,
    isMockData: true,
    disclaimer: DISCLAIMER,
  };
}
